package com.ecoriego.app.ui;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import com.ecoriego.app.R;import com.ecoriego.app.data.DBHelper;import com.ecoriego.app.model.*;import com.ecoriego.app.adapter.RiegoAdapter;import java.util.*;
public class PlantaDetalleActivity extends AppCompatActivity{DBHelper db;Planta p;RiegoAdapter ad;TextView estado,info;double temp=0;boolean lluvia=false;int rainChance=0;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_planta_detalle);db=new DBHelper(this);temp=getSharedPreferences("weather",MODE_PRIVATE).getFloat("temp",0);rainChance=getSharedPreferences("weather",MODE_PRIVATE).getInt("rain",0);lluvia=rainChance>=60;int id=getIntent().getIntExtra("id",-1);p=db.obtenerPlanta(id);if(p==null){finish();return;}((TextView)findViewById(R.id.tvDetalleNombre)).setText(p.getNombre());((TextView)findViewById(R.id.tvDetalleEspecie)).setText(p.getEspecie());estado=findViewById(R.id.tvDetalleEstado);info=findViewById(R.id.tvDetalleInfo);actualizar();RecyclerView rv=findViewById(R.id.recyclerBitacora);rv.setLayoutManager(new LinearLayoutManager(this));ad=new RiegoAdapter(db.riegosDePlanta(p.getId()));rv.setAdapter(ad);findViewById(R.id.btnRegar).setOnClickListener(v->{db.registrarRiego(p.getId(),temp,lluvia);Toast.makeText(this,"Riego registrado en la bitácora.",Toast.LENGTH_SHORT).show();ad.setData(db.riegosDePlanta(p.getId()));actualizar();});findViewById(R.id.btnEditar).setOnClickListener(v->{Intent i=new Intent(this,PlantaFormActivity.class);i.putExtra("id",p.getId());startActivity(i);});findViewById(R.id.btnEliminar).setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Eliminar planta").setMessage("Esta acción también eliminará su bitácora de riego.").setNegativeButton("Cancelar",null).setPositiveButton("Eliminar",(d,w)->{db.eliminarPlanta(p.getId());finish();}).show());}void actualizar(){List<Riego> r=db.riegosDePlanta(p.getId());boolean due=r.isEmpty();if(!due){long ms=System.currentTimeMillis()-parse(r.get(0).getFechaHora());due=ms>=p.getFrecuencia()*86400000L;}if(rainChance>=60){estado.setText("LLUVIA HOY · AJUSTA EL RIEGO");}else{estado.setText(due?"NECESITA RIEGO":"AL DÍA");}info.setText("Siembra: "+p.getFechaSiembra()+"  ·  "+p.getUbicacion()+"\n"+(p.getNotas().isEmpty()?"Sin notas.":p.getNotas()));((TextView)findViewById(R.id.tvDetalleRiego)).setText("Riego cada "+p.getFrecuencia()+" días");}long parse(String s){try{return new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.getDefault()).parse(s).getTime();}catch(Exception e){return System.currentTimeMillis();}}}
